//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_EthernetFramesTxIn(value: *mut SW::StructuredEthernetMessage_i) -> bool;
  fn get_EthernetFramesTxIn_num_invalid() -> u64;
  fn get_CurrentMode(value: *mut SW::Mode) -> bool;
  fn get_CurrentMode_num_invalid() -> u64;
  fn put_EthernetFramesTxOut(value: *mut SW::StructuredEthernetMessage_i) -> bool;
  fn put_AttackStatusTx(value: *mut SW::AttackStatus) -> bool;
}

pub fn unsafe_get_EthernetFramesTxIn() -> Option<SW::StructuredEthernetMessage_i>
{
  unsafe {
    let value: *mut SW::StructuredEthernetMessage_i = &mut SW::StructuredEthernetMessage_i::default();
    if (get_EthernetFramesTxIn(value)) {
      return Some(*value);
    } else {
      return None;
    }
  }
}

pub fn unsafe_get_EthernetFramesTxIn_num_invalid() -> u64
{
  unsafe {
    return get_EthernetFramesTxIn_num_invalid();
  }
}

pub fn unsafe_get_CurrentMode() -> SW::Mode
{
  unsafe {
    let value: *mut SW::Mode = &mut SW::Mode::default();
    get_CurrentMode(value);
    return *value;
  }
}

pub fn unsafe_get_CurrentMode_num_invalid() -> u64
{
  unsafe {
    return get_CurrentMode_num_invalid();
  }
}

pub fn unsafe_put_EthernetFramesTxOut(value: &SW::StructuredEthernetMessage_i) -> bool
{
  unsafe {
    return put_EthernetFramesTxOut(value as *const SW::StructuredEthernetMessage_i as *mut SW::StructuredEthernetMessage_i);
  }
}

pub fn unsafe_put_AttackStatusTx(value: &SW::AttackStatus) -> bool
{
  unsafe {
    return put_AttackStatusTx(value as *const SW::AttackStatus as *mut SW::AttackStatus);
  }
}

