#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_EthernetFramesTxIn: Mutex<Option<SW::StructuredEthernetMessage_i>> = Mutex::new(None);
  pub static ref IN_CurrentMode: Mutex<Option<SW::Mode>> = Mutex::new(None);
  pub static ref OUT_EthernetFramesTxOut: Mutex<Option<SW::StructuredEthernetMessage_i>> = Mutex::new(None);
  pub static ref OUT_AttackStatusTx: Mutex<Option<SW::AttackStatus>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_EthernetFramesTxIn.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_CurrentMode.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_EthernetFramesTxOut.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_AttackStatusTx.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_EthernetFramesTxIn(value: *mut SW::StructuredEthernetMessage_i) -> bool
{
  unsafe {
    match *IN_EthernetFramesTxIn.lock().unwrap_or_else(|e| e.into_inner()) {
      Some(v) => {
        *value = v;
        return true;
      },
      None => return false,
    }
  }
}

#[cfg(test)]
pub fn get_EthernetFramesTxIn_num_invalid() -> u64
{
  return 0;
}

#[cfg(test)]
pub fn get_CurrentMode(value: *mut SW::Mode) -> bool
{
  unsafe {
    let guard = IN_CurrentMode.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_CurrentMode_num_invalid() -> u64
{
  return 0;
}

#[cfg(test)]
pub fn put_EthernetFramesTxOut(value: *mut SW::StructuredEthernetMessage_i) -> bool
{
  unsafe {
    *OUT_EthernetFramesTxOut.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}

#[cfg(test)]
pub fn put_AttackStatusTx(value: *mut SW::AttackStatus) -> bool
{
  unsafe {
    *OUT_AttackStatusTx.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
